"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[1490],{89969(e){e.exports=JSON.parse('{"tag":{"label":"modes","permalink":"/es/tags/modes","allTagsPath":"/es/tags","count":17,"items":[{"id":"modes/scan","title":"An\xe1lisis (solo lectura)","description":"Revise las ra\xedces de cach\xe9, las descargas incompletas y otros candidatos de limpieza de Linux sin eliminar archivos.","permalink":"/es/modes/scan"},{"id":"modes/personal-stale-files","title":"Archivos personales sin uso","description":"El modo solo interactivo que busca archivos grandes y sin usar desde hace tiempo en ~/Downloads y en ra\xedces sin protecci\xf3n configuradas.","permalink":"/es/modes/personal-stale-files"},{"id":"modes/node-modules-finder","title":"Buscador de node_modules abandonados","description":"Busque directorios node_modules en proyectos sin tocar durante N d\xedas o m\xe1s y elim\xednelos de forma interactiva. A menudo es lo que m\xe1s espacio libera en el equipo de un desarrollador.","permalink":"/es/modes/node-modules-finder"},{"id":"modes/partial-downloads","title":"Descargas incompletas o hu\xe9rfanas","description":"Busque y elimine archivos de descargas incompletas abandonados (.crdownload, .part y .fdmdownload) que dejan las transferencias interrumpidas de navegadores y gestores de descargas.","permalink":"/es/modes/partial-downloads"},{"id":"modes/speed","title":"Diagn\xf3stico de velocidad","description":"Revise la temperatura, la presi\xf3n y el trabajo de arranque de Linux, y decida si aplica cada cambio propuesto.","permalink":"/es/modes/speed"},{"id":"modes/doctor","title":"Doctor","description":"Detecte runtimes instalados en el disco pero ausentes del arranque de la shell (nvm, pnpm, bun, deno, cargo) y a\xf1ada el bloque de inicio est\xe1ndar con su confirmaci\xf3n. Solo a\xf1ade.","permalink":"/es/modes/doctor"},{"id":"modes/editor-extensions","title":"Extensiones de editores","description":"Elimine las versiones sustituidas de extensiones de VS Code y Cursor (las copias antiguas que quedan al actualizarse una extensi\xf3n), sujeto a una comprobaci\xf3n de sustituci\xf3n y al filtro de inactividad.","permalink":"/es/modes/editor-extensions"},{"id":"modes/reports","title":"Informes","description":"El recorrido guiado puede escribir un registro JSON de la sesi\xf3n. Liste, vea, convierta a Markdown o HTML y exporte esos registros.","permalink":"/es/modes/reports"},{"id":"modes/system-cleanup","title":"Limpieza del sistema (sudo)","description":"El modo de sistema con sudo: apt, registro del sistema, Snap, lista de kernels, archivos antiguos de /tmp y vaciado opcional de la cach\xe9 de p\xe1ginas.","permalink":"/es/modes/system-cleanup"},{"id":"modes/menu","title":"Men\xfa","description":"El men\xfa numerado que permite ejecutar una sola categor\xeda de linux-cleanup cada vez en lugar del recorrido completo.","permalink":"/es/modes/menu"},{"id":"modes/walkthrough","title":"Recorrido guiado (predeterminado)","description":"El modo predeterminado de linux-cleanup: diez pasos guiados por todas las categor\xedas de limpieza, con pregunta antes de cada uno, total acumulado e informe JSON de la sesi\xf3n.","permalink":"/es/modes/walkthrough"},{"id":"modes/overview","title":"Resumen de modos","description":"Todos los modos de linux-cleanup agrupados por lo que hacen: inspecci\xf3n de solo lectura, limpieza guiada y por lotes, modos interactivos de datos personales y ayudantes de salida y reparaci\xf3n.","permalink":"/es/modes/overview"},{"id":"modes/globals-audit","title":"Revisi\xf3n de paquetes globales","description":"Una revisi\xf3n de solo lectura de los paquetes instalados globalmente con npm, pnpm, yarn, bun y deno, que marca cada uno como usado recientemente, como dependencia o sin uso, e imprime comandos de desinstalaci\xf3n que ejecuta usted.","permalink":"/es/modes/globals-audit"},{"id":"modes/home-audit","title":"Revisi\xf3n del directorio personal","description":"Una lista de solo lectura de las 20 entradas m\xe1s grandes de su directorio personal, pueda o no limpiarlas linux-cleanup: la forma m\xe1s r\xe1pida de saber qu\xe9 ocupa de verdad el disco.","permalink":"/es/modes/home-audit"},{"id":"reference/modes-matrix","title":"Tabla de modos","description":"Todos los modos de linux-cleanup lado a lado: si eliminan, si son interactivos, si usan sudo y si escriben un registro de sesi\xf3n.","permalink":"/es/reference/modes-matrix"},{"id":"modes/all-safe","title":"Totalmente seguro (por lotes)","description":"Limpie todas las cach\xe9s regenerables de una sola pasada. El modo pensado para cron y el mantenimiento desatendido, y el \xfanico al que se aplica --yes.","permalink":"/es/modes/all-safe"},{"id":"modes/tui","title":"TUI (men\xfa visual)","description":"El men\xfa visual con whiptail o dialog a\xf1adido en linux-cleanup 1.3.0, que vuelve al men\xfa de la CLI si no hay ninguno instalado.","permalink":"/es/modes/tui"}],"unlisted":false}}')}}]);